224	    /**
225	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
226	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
227	     * does not catch). The names of all offending fields are collected so the caller receives a
228	     * 400 response whose {@code errors} array lists each one.
229	     */
230	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
231	        List<String> missingFields = new ArrayList<>();
232	        if (isBlank(ownerFieldsDto.getFirstName())) {
233	            missingFields.add("firstName");
234	        }
235	        if (isBlank(ownerFieldsDto.getLastName())) {
236	            missingFields.add("lastName");
237	        }
238	        if (isBlank(ownerFieldsDto.getAddress())) {
239	            missingFields.add("address");
240	        }
241	        if (isBlank(ownerFieldsDto.getCity())) {
242	            missingFields.add("city");
243	        }
